  "claims": [
    {
      "claim_id": "C1",
      "claim": "Бак теплоснабжения К22 на плане и разрезе подписан как 1000 л.",
      "status": "supported",
      "reason": "На плане и разрезе 18–18 присутствует обозначение К22 с объёмом 1000 л. Это подтверждает подпись проектного оборудования, но не фактически установленный объём.",
      "evidence": [
        {
          "type": "image",
          "block_id": "blk_cc80e7962a094791b984d8fb5391e886",
          "image_sha256": "df5eab1b75e59001cf78cb3cded3596c55d5726badde250c456889c012e1a3b3",
          "bbox_norm_xyxy": [0.17, 0.73, 0.275, 0.844],
          "observation": "В нижней левой части плана рядом с двумя круглыми изображениями баков размещена подпись «К22 бак теплоснабжения 1000л»."
        },
        {
          "type": "image",
          "block_id": "blk_27af51f0cd26488ea08ffa55589b0c3e",
          "image_sha256": "9ae3ec6ff303ff8f3b6317bd8cfa1b49ab22653581184818e10d9f0393bf4c7a",
          "bbox_norm_xyxy": [0.778, 0.396, 0.839, 0.887],
          "observation": "Справа на разрезе 18–18 изображён бак с подписью «К22 бак теплоснабжения 1000л»."
        }
      ]
    },
    {
      "claim_id": "C2",
      "claim": "Бак ДОО К23 на плане подписан как 100 л.",
      "status": "supported",
      "reason": "Подпись К23 с объёмом 100 л видна на плане; такой же объём обозначен на аксонометрии и плане дренажных трубопроводов.",
      "evidence": [
        {
          "type": "image",
          "block_id": "blk_cc80e7962a094791b984d8fb5391e886",
          "image_sha256": "df5eab1b75e59001cf78cb3cded3596c55d5726badde250c456889c012e1a3b3",
          "bbox_norm_xyxy": [0.835, 0.554, 0.886, 0.588],
          "observation": "У круглого бака в правой части плана стоит подпись «К23 бак ДОО 100л»."
        },
        {
          "type": "image",
          "block_id": "blk_94b58ecf5d404f7d90c272d267eb2e48",
          "image_sha256": "5046f5ee795097687ef038dbc5f114b238922c100bbbab0af0e84f1089f400af",
          "bbox_norm_xyxy": [0.652, 0.709, 0.71, 0.763],
          "observation": "На аксонометрии рядом с небольшим баком указано «К23 бак ДОО 100л»."
        },
        {
          "type": "image",
          "block_id": "blk_06029d59a01b4b779037ffcee1ae5260",
          "image_sha256": "99f0948dd8e59ee31f68b9f79a58131e5fa3a0fc63e5fdfcb0a541f00871bb8c",
          "bbox_norm_xyxy": [0.825, 0.556, 0.883, 0.597],
          "observation": "На плане дренажных трубопроводов сохранена подпись «К23 бак ДОО 100л»."
        }
      ]
    },
    {
      "claim_id": "C3",
      "claim": "Спецификация задаёт два бака теплоснабжения по 1500 л.",
      "status": "needs_data",
      "reason": "Спецификация не приложена, authoritative_text пуст. Утверждение проверяемого замечания не является независимым подтверждением объёма и количества.",
      "evidence": [],
      "missing_data": [
        "Строка спецификации баков К22 с объёмом, единицей измерения и количеством."
      ],
      "context_queries": ["К22", "1500"]
    },
    {
      "claim_id": "C4",
      "claim": "Спецификация задаёт бак ДОО К23 объёмом 200 л.",
      "status": "needs_data",
      "reason": "В приложенных материалах отсутствует строка спецификации, подтверждающая объём 200 л и её связь с К23.",
      "evidence": [],
      "missing_data": [
        "Строка спецификации бака К23 с объёмом и идентификацией оборудования."
      ],
      "context_queries": ["К23", "200", "бак ДОО"]
    },
    {
      "claim_id": "C5",
      "claim": "Объёмы баков на чертежах отличаются от спецификации.",
      "status": "needs_data",
      "reason": "Подписи на чертежах подтверждаются, но сторона сравнения со спецификацией отсутствует. При подтверждении заявленных строк это будет противоречие проектных обозначений; физический дефект или неправильный подбор объёма из этих материалов не следует.",
      "evidence": [],
      "missing_data": [
        "Спецификация той же версии проекта со строками К22 и К23.",
        "Для оценки правильности подбора — расчёт требуемых объёмов баков."
      ],
      "context_queries": ["К22", "К23", "1500", "200"]
    },
    {
      "claim_id": "C6",
      "claim": "По описаниям листов нельзя надёжно определить количество всех изображённых баков.",
      "status": "needs_data",
      "reason": "Описания листов не предоставлены, поэтому их достаточность проверить нельзя. На плане и аксонометрии визуально показаны два бака возле обозначения К22; один бак на отдельном разрезе не опровергает это количество. Эти виды нельзя суммировать как разные экземпляры оборудования. Полнота учёта всех баков требует сопоставления позиций.",
      "evidence": [
        {
          "type": "image",
          "block_id": "blk_94b58ecf5d404f7d90c272d267eb2e48",
          "image_sha256": "5046f5ee795097687ef038dbc5f114b238922c100bbbab0af0e84f1089f400af",
          "bbox_norm_xyxy": [0.134, 0.641, 0.21, 0.82],
          "observation": "В левой нижней части аксонометрии показаны два вертикальных цилиндрических бака рядом с подписью К22."
        }
      ],
      "missing_data": [
        "Описания листов, достаточность которых оспаривается.",
        "Перечень позиций баков с количеством и привязкой к изображениям."
      ],
      "context_queries": ["К22", "К23", "бак", "Количество"]
    }
  ]
}
